(function(global){"use strict";const DATA={"area":{"id":"social-studies","shortTitle":"Social Studies","eyebrow":"Texas social studies certification preparation","heroTitle":"Read the sources. Trace the causes. Defend the conclusion.","heroText":"Diagnostics and targeted practice for EC–6 Social Studies 903, Core Subjects 4–8 Social Studies 808, and standalone Social Studies 4–8 (118).","about":"The social studies site includes disciplinary content, source and map analysis, historical reasoning, civic and economic applications, and the instruction-and-assessment competencies included in the official frameworks.","links":[{"label":"Core Subjects EC–6 (391) framework — Social Studies 903","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_391.htm"},{"label":"Core Subjects 4–8 (211) framework — Social Studies 808","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_211_2021.htm"},{"label":"Social Studies 4–8 (118) framework","url":"https://www.tx.nesinc.com/Content/StudyGuide/TX_SG_obj_118.htm"}]},"categories":{"ss-texas":{"label":"Texas History","description":"Indigenous societies, Spanish and Mexican Texas, revolution, republic, statehood, Civil War, economic development, and modern Texas.","group":"History","questions":[{"prompt":"Which Indigenous group of the Texas Panhandle was especially associated with bison hunting and the use of horses?","correct":"Comanche","distractors":["Caddo","Karankawa","Coahuiltecan"],"explanation":"The Comanche became powerful mounted bison hunters on the Southern Plains."},{"prompt":"Spanish missions in Texas were established primarily to:","correct":"extend Spanish influence and convert Indigenous peoples to Christianity.","distractors":["create factories for northern industry.","support British settlement.","prepare Texas for immediate U.S. statehood."],"explanation":"Missions were religious and imperial institutions that accompanied Spanish colonization."},{"prompt":"The empresario system in Mexican Texas was designed to:","correct":"bring settlers to Texas under contracts with colonization agents.","distractors":["end all immigration into Texas.","replace ranching with mining.","create a national bank."],"explanation":"Empresarios such as Stephen F. Austin recruited and settled families under Mexican land policies."},{"prompt":"Which issue contributed significantly to tensions between many Anglo settlers and the Mexican government before the Texas Revolution?","correct":"Disputes over immigration, local autonomy, and enforcement of Mexican laws","distractors":["A conflict over building the transcontinental railroad","Opposition to the Louisiana Purchase","The discovery of oil at Spindletop"],"explanation":"Immigration restrictions, centralization, customs enforcement, and slavery were among the growing tensions."},{"prompt":"The Battle of the Alamo occurred in:","correct":"1836.","distractors":["1776.","1845.","1861."],"explanation":"The Alamo fell in March 1836 during the Texas Revolution."},{"prompt":"Texas won decisive independence from Mexico at the Battle of:","correct":"San Jacinto.","distractors":["Gonzales.","Goliad.","Palo Alto."],"explanation":"Sam Houston’s forces defeated Santa Anna at San Jacinto on April 21, 1836."},{"prompt":"Which statement best describes the Republic of Texas?","correct":"It was an independent nation from 1836 until annexation by the United States in 1845.","distractors":["It was a Spanish mission district from 1901 to 1945.","It joined the Confederacy immediately after independence.","It was never recognized by any foreign government."],"explanation":"Texas functioned as an independent republic for nearly a decade."},{"prompt":"Texas entered the United States as a state in:","correct":"1845.","distractors":["1821.","1836.","1876."],"explanation":"The United States annexed Texas in 1845."},{"prompt":"A major immediate cause of the U.S.–Mexican War was disagreement over:","correct":"the Texas–Mexico boundary and U.S. annexation of Texas.","distractors":["the location of the Oregon Trail.","control of the Great Lakes.","the purchase of Alaska."],"explanation":"Mexico rejected annexation, and the United States and Mexico disputed whether the border was the Nueces River or Rio Grande."},{"prompt":"During the Civil War, Texas joined:","correct":"the Confederacy.","distractors":["the Union as a free state.","Mexico.","the Republic of Texas as a neutral nation."],"explanation":"Texas seceded from the United States in 1861 and joined the Confederate States."},{"prompt":"Juneteenth commemorates:","correct":"the announcement in Galveston on June 19, 1865, that enslaved people in Texas were free.","distractors":["Texas independence from Mexico.","the annexation of Texas.","the discovery of oil."],"explanation":"General Order No. 3 announced emancipation in Texas on June 19, 1865."},{"prompt":"The Constitution of 1876 remains important because it:","correct":"is the foundation of the current Texas state government.","distractors":["created the Republic of Texas.","ended the Texas Revolution.","made Texas a territory."],"explanation":"The 1876 constitution, with many amendments, still structures Texas government."},{"prompt":"The discovery at Spindletop in 1901 accelerated the growth of which Texas industry?","correct":"Oil and petroleum","distractors":["Cotton textiles only","Commercial fishing only","Airplane manufacturing only"],"explanation":"The Spindletop gusher helped launch the modern Texas petroleum industry."},{"prompt":"Railroads contributed to nineteenth-century Texas development chiefly by:","correct":"connecting farms, ranches, towns, and markets while encouraging settlement.","distractors":["eliminating all long-distance trade.","preventing urban growth.","ending cattle production immediately."],"explanation":"Rail transportation lowered shipping costs and linked Texas to national markets."},{"prompt":"The cattle drives of the late nineteenth century moved herds mainly from Texas to:","correct":"railheads farther north, where cattle could be shipped to eastern markets.","distractors":["Spanish missions on the Gulf Coast.","plantations in New England.","ports in Alaska."],"explanation":"Trails such as the Chisholm Trail connected Texas herds with northern railroads."},{"prompt":"Which industry became especially important to the economy of West Texas?","correct":"Cattle ranching and later oil and gas production","distractors":["Shipbuilding on the Atlantic coast","Rice cultivation in mountain valleys","Commercial whaling"],"explanation":"The region’s grasslands supported ranching, and later petroleum resources shaped development."},{"prompt":"The Dust Bowl affected parts of Texas during the 1930s by:","correct":"damaging farms through drought, wind erosion, and severe dust storms.","distractors":["creating abundant rainfall.","ending migration from rural areas.","increasing soil fertility everywhere."],"explanation":"Drought and poor land practices exposed soil to wind erosion, forcing many families to move."},{"prompt":"Which Texas city grew as a major port and petrochemical center along the Houston Ship Channel?","correct":"Houston","distractors":["Amarillo","Lubbock","Abilene"],"explanation":"The ship channel connected Houston to the Gulf and supported refining, shipping, and manufacturing."},{"prompt":"Lyndon B. Johnson is significant in Texas and U.S. history because he:","correct":"served as president and promoted Great Society and civil-rights legislation.","distractors":["commanded at the Alamo.","founded the Republic of Texas.","discovered Spindletop."],"explanation":"Johnson, a Texan, became the 36th president and supported major domestic reforms."},{"prompt":"Which demographic trend has most shaped modern Texas?","correct":"Rapid population growth, urbanization, and increasing cultural diversity","distractors":["A steady return to a small rural population","The disappearance of international trade","A complete end to migration from other states"],"explanation":"Texas has grown rapidly through migration, immigration, natural increase, and metropolitan expansion."}]},"ss-us":{"label":"United States History","description":"Founding, expansion, sectional conflict, Civil War, industrialization, reform, world wars, civil rights, and modern developments.","group":"History","questions":[{"prompt":"The Declaration of Independence primarily announced that:","correct":"the colonies considered themselves free and independent states and explained their grievances.","distractors":["the Constitution had been ratified.","slavery had ended nationwide.","the United States had purchased Louisiana."],"explanation":"Adopted in 1776, it asserted independence and justified separation from Britain."},{"prompt":"The Articles of Confederation created a national government that was:","correct":"too weak to tax directly or regulate interstate commerce effectively.","distractors":["headed by a powerful hereditary king.","organized into three strong branches.","able to veto all state laws."],"explanation":"The Articles preserved state sovereignty and gave Congress limited powers."},{"prompt":"The Great Compromise at the Constitutional Convention created:","correct":"a bicameral Congress with representation by population in the House and equality in the Senate.","distractors":["a single legislative chamber.","direct election of the president by Congress only.","a national church."],"explanation":"The compromise balanced large- and small-state interests."},{"prompt":"The first ten amendments to the Constitution are called the:","correct":"Bill of Rights.","distractors":["Federalist Papers.","Articles of Confederation.","Emancipation Proclamation."],"explanation":"Ratified in 1791, the Bill of Rights protects individual liberties and limits government."},{"prompt":"Marbury v. Madison established the principle of:","correct":"judicial review.","distractors":["popular sovereignty in territories.","nullification by state governors.","direct election of senators."],"explanation":"The Supreme Court asserted authority to declare laws unconstitutional."},{"prompt":"The Louisiana Purchase of 1803:","correct":"roughly doubled the territory of the United States.","distractors":["ended the Civil War.","acquired Alaska from Russia.","created the original thirteen colonies."],"explanation":"The United States purchased a vast territory from France."},{"prompt":"The Monroe Doctrine warned European powers against:","correct":"new colonization or interference in the Western Hemisphere.","distractors":["trade with Asia.","industrialization in Britain.","westward settlement by Americans."],"explanation":"The 1823 policy opposed further European political intervention in the Americas."},{"prompt":"The term Manifest Destiny was used to justify:","correct":"continental expansion of the United States.","distractors":["ending all immigration.","returning western lands to Britain.","abolishing federal territories."],"explanation":"Many Americans portrayed westward expansion as a national mission."},{"prompt":"The Missouri Compromise attempted to preserve sectional balance by:","correct":"admitting Missouri as a slave state and Maine as a free state while limiting slavery in part of the Louisiana Territory.","distractors":["ending slavery in every state.","admitting California and Texas together.","creating the Federal Reserve."],"explanation":"The 1820 compromise temporarily balanced free and slave states."},{"prompt":"The abolitionist movement sought primarily to:","correct":"end slavery.","distractors":["expand the plantation system.","restore British rule.","limit public education."],"explanation":"Abolitionists used moral, religious, political, and legal arguments against slavery."},{"prompt":"The immediate issue that triggered secession in 1860–1861 was:","correct":"the election of Abraham Lincoln amid conflict over slavery and its expansion.","distractors":["the Louisiana Purchase.","the War of 1812.","the annexation of Hawaii."],"explanation":"Southern leaders viewed Lincoln’s election as a threat to slavery, which secession declarations defended."},{"prompt":"The Emancipation Proclamation declared free enslaved people in:","correct":"areas under Confederate control, effective January 1, 1863.","distractors":["all border states immediately.","the entire Western Hemisphere.","only Washington, D.C."],"explanation":"It was a wartime measure applying to rebelling areas, not all slaveholding states."},{"prompt":"The Thirteenth Amendment:","correct":"abolished slavery in the United States, except as punishment for crime.","distractors":["guaranteed women the vote.","created the income tax.","established direct election of senators."],"explanation":"Ratified in 1865, it ended legal slavery nationwide with the stated exception."},{"prompt":"The Fourteenth Amendment established:","correct":"national citizenship and equal protection of the laws.","distractors":["prohibition of alcohol.","the electoral college.","the two-term presidential limit."],"explanation":"The amendment transformed constitutional protections of citizenship and civil rights."},{"prompt":"The Fifteenth Amendment prohibited denying the vote on the basis of:","correct":"race, color, or previous condition of servitude.","distractors":["age under eighteen.","property ownership only.","religious affiliation only."],"explanation":"Ratified in 1870, it addressed racial restrictions on male voting, though enforcement was weak."},{"prompt":"Industrialization in the late nineteenth century encouraged:","correct":"urbanization, factory growth, immigration, and the expansion of wage labor.","distractors":["the disappearance of railroads.","a return to household subsistence only.","the end of corporate business."],"explanation":"Factories and transportation networks concentrated workers and capital in cities."},{"prompt":"Progressive Era reformers commonly sought to:","correct":"address problems associated with industrialization, urbanization, and political corruption.","distractors":["restore the Articles of Confederation.","expand child labor.","eliminate public-health regulation."],"explanation":"Progressives promoted reforms in government, labor, public health, and consumer protection."},{"prompt":"The United States entered World War I in:","correct":"1917.","distractors":["1898.","1929.","1941."],"explanation":"The United States declared war on Germany in April 1917."},{"prompt":"The Great Depression began after:","correct":"a severe economic contraction associated with the 1929 stock-market crash and banking failures.","distractors":["the ratification of the Constitution.","the invention of the telegraph.","the Louisiana Purchase."],"explanation":"The crash was one event in a deeper collapse involving banking, demand, credit, and production."},{"prompt":"The New Deal expanded the federal government’s role by:","correct":"creating relief, recovery, regulatory, and social-insurance programs.","distractors":["abolishing every state government.","ending all taxes.","privatizing Social Security."],"explanation":"Roosevelt’s administration used federal programs to respond to the Depression."},{"prompt":"The attack on Pearl Harbor led directly to:","correct":"U.S. entry into World War II.","distractors":["the start of Reconstruction.","the end of the Korean War.","ratification of the Bill of Rights."],"explanation":"After the December 7, 1941 attack, Congress declared war on Japan."},{"prompt":"The Cold War was primarily a geopolitical and ideological rivalry between:","correct":"the United States and the Soviet Union.","distractors":["the United States and Canada.","France and Spain in the 1500s.","the Union and Confederacy."],"explanation":"The rivalry involved alliances, nuclear competition, proxy wars, and competing political-economic systems."},{"prompt":"Brown v. Board of Education held that:","correct":"racial segregation in public schools violated the Equal Protection Clause.","distractors":["separate schools were always equal.","Congress could not regulate interstate commerce.","women could not vote."],"explanation":"The 1954 decision rejected legally segregated public education."},{"prompt":"The Civil Rights Act of 1964:","correct":"prohibited discrimination in major areas including public accommodations and employment.","distractors":["created the electoral college.","ended the Revolutionary War.","required segregated schools."],"explanation":"The act was a landmark federal civil-rights law."},{"prompt":"The Voting Rights Act of 1965 was designed chiefly to:","correct":"protect voting rights against racial discrimination.","distractors":["lower tariffs on imports.","create national parks.","limit voting to property owners."],"explanation":"It targeted practices that had excluded Black citizens from voting, especially in the South."}]},"ss-world":{"label":"World History and Civilizations","description":"Early civilizations, classical societies, world religions, exchange networks, revolutions, industrialization, imperialism, and global conflict.","group":"History","questions":[{"prompt":"The Neolithic Revolution refers to the transition from:","correct":"hunting and gathering to settled agriculture.","distractors":["industrial factories to farming.","monarchy to democracy everywhere.","bronze tools to stone tools."],"explanation":"Agriculture enabled permanent settlements, population growth, and occupational specialization."},{"prompt":"River-valley civilizations developed near rivers primarily because rivers provided:","correct":"water, fertile soil, transportation, and irrigation opportunities.","distractors":["complete protection from invasion.","unlimited metal ores.","freedom from flooding."],"explanation":"Rivers supported farming and trade, though floods could also be destructive."},{"prompt":"A major contribution of ancient Greece was the development of:","correct":"democratic ideas, philosophy, drama, and systematic inquiry.","distractors":["movable-type printing.","the steam engine.","the compass."],"explanation":"Greek city-states and thinkers strongly influenced later political and intellectual traditions."},{"prompt":"The Roman Republic influenced later governments through ideas such as:","correct":"representative institutions, written law, and civic duty.","distractors":["absolute rule without law.","the abolition of citizenship.","a prohibition on elected offices."],"explanation":"Roman institutions and legal traditions shaped later republican thought."},{"prompt":"The Silk Roads connected regions of Eurasia and facilitated:","correct":"trade and the exchange of religions, technologies, diseases, and ideas.","distractors":["only military conquest with no commerce.","the isolation of China from all outsiders.","travel only across the Atlantic."],"explanation":"Long-distance networks moved both goods and cultural or biological influences."},{"prompt":"The spread of Islam after the seventh century created:","correct":"a broad cultural and commercial zone linking parts of Africa, Asia, and Europe.","distractors":["a single nation with no diversity.","the end of scholarship in the Mediterranean.","the disappearance of urban trade."],"explanation":"Muslim societies were diverse but connected through religion, commerce, and intellectual exchange."},{"prompt":"Feudalism in medieval Europe was characterized by:","correct":"landholding relationships, local obligations, and decentralized political authority.","distractors":["industrial wage labor in large factories.","universal direct democracy.","central banking controlled by elected parliaments."],"explanation":"Political and military obligations were often tied to land and personal relationships."},{"prompt":"The Renaissance began in Italian city-states and emphasized:","correct":"renewed interest in classical learning, humanism, and artistic innovation.","distractors":["rejection of all ancient texts.","ending commerce in cities.","the immediate abolition of monarchy."],"explanation":"Humanists studied classical works and emphasized human creativity and education."},{"prompt":"The Protestant Reformation challenged:","correct":"the authority and practices of the Roman Catholic Church in western Europe.","distractors":["Buddhist rule in India.","the Roman Republic.","the Atlantic slave trade directly."],"explanation":"Reformers such as Luther criticized church practices and contributed to new Christian denominations."},{"prompt":"European overseas exploration in the fifteenth and sixteenth centuries was encouraged by:","correct":"commercial goals, new navigation technologies, state competition, and missionary aims.","distractors":["a desire to end all trade.","the disappearance of ocean-going vessels.","industrial railroads."],"explanation":"Multiple motives and technological developments supported long-distance voyages."},{"prompt":"The Columbian Exchange involved the transfer of:","correct":"plants, animals, people, diseases, and ideas between the Eastern and Western Hemispheres.","distractors":["only precious metals within Europe.","only religious texts within Asia.","no biological organisms."],"explanation":"The exchange transformed diets, populations, environments, and economies on both sides of the Atlantic."},{"prompt":"The Enlightenment emphasized:","correct":"reason, natural rights, and the possibility of improving government and society.","distractors":["divine-right monarchy as beyond criticism.","ending scientific inquiry.","returning to feudal isolation."],"explanation":"Enlightenment thinkers applied reason to politics, law, religion, and social institutions."},{"prompt":"The French Revolution began in 1789 amid conflict over:","correct":"social inequality, fiscal crisis, political representation, and Enlightenment ideas.","distractors":["the invention of the airplane.","the division of Germany after World War II.","the fall of the Roman Empire."],"explanation":"Economic crisis and unequal privileges intensified demands for political change."},{"prompt":"The Industrial Revolution first developed in Britain and transformed production through:","correct":"mechanization, factories, fossil-fuel energy, and new transportation.","distractors":["a return to hand production only.","the elimination of cities.","the end of international trade."],"explanation":"Industrialization increased output and altered work, class structures, urban life, and the environment."},{"prompt":"Nineteenth-century imperialism involved:","correct":"powerful states extending political and economic control over other regions.","distractors":["the end of overseas empires.","universal national self-determination.","the abolition of military competition."],"explanation":"Industrial powers built empires through conquest, settlement, trade control, and unequal treaties."},{"prompt":"Nationalism contributed to both:","correct":"the unification of states and conflicts among ethnic or national groups.","distractors":["the disappearance of national identities.","the end of political revolutions.","a single global government."],"explanation":"Nationalism could unify populations but also intensify rivalry and exclusion."},{"prompt":"World War I was intensified by alliances, militarism, imperial rivalry, and:","correct":"nationalism.","distractors":["the absence of modern weapons.","complete economic isolation.","the United Nations."],"explanation":"The assassination at Sarajevo triggered a crisis within a system already shaped by these tensions."},{"prompt":"The Russian Revolution of 1917 led to:","correct":"the eventual creation of the Soviet Union under communist rule.","distractors":["restoration of the Roman Republic.","unification of Italy.","the Meiji Restoration."],"explanation":"Bolshevik victory in the revolution and civil war produced the Soviet state."},{"prompt":"The Holocaust was the systematic murder of:","correct":"six million Jews and millions of other victims by Nazi Germany and its collaborators.","distractors":["soldiers only on the western front.","European monarchs during the Renaissance.","colonists in the American Revolution."],"explanation":"Nazi racial ideology and state power produced genocide during World War II."},{"prompt":"Decolonization after World War II refers to:","correct":"the end of many European empires and the creation of independent states.","distractors":["the expansion of feudalism.","the establishment of Roman colonies.","the closing of all international organizations."],"explanation":"Nationalist movements and weakened empires contributed to independence across Asia, Africa, and elsewhere."}]},"ss-geography":{"label":"Geography and Human–Environment Interaction","description":"Maps, regions, climate, migration, population, urbanization, resources, settlement, and spatial analysis.","group":"Geography","questions":[{"prompt":"Latitude measures distance:","correct":"north or south of the equator.","distractors":["east or west of the prime meridian.","above sea level only.","between time zones only."],"explanation":"Lines of latitude run east-west and locate positions north or south."},{"prompt":"Longitude measures distance:","correct":"east or west of the prime meridian.","distractors":["north or south of the equator.","from the center of Earth.","above a mountain summit."],"explanation":"Meridians locate positions east or west and help define time zones."},{"prompt":"A map scale is used to:","correct":"relate distance on a map to distance on Earth.","distractors":["show only elevation.","identify the map author.","determine latitude without coordinates."],"explanation":"Scale converts mapped measurements into real-world distance."},{"prompt":"Which map would best show population density by state?","correct":"A thematic choropleth map","distractors":["A physical-relief map only","A road map with no data shading","A star chart"],"explanation":"Choropleth shading can represent rates or densities across areas."},{"prompt":"A region defined by shared characteristics such as climate or language is a:","correct":"formal region.","distractors":["perceptual distance.","absolute location.","time zone only."],"explanation":"Formal regions are organized around one or more measurable common traits."},{"prompt":"A metropolitan area organized around a central city and commuting patterns is a:","correct":"functional region.","distractors":["formal climate region only.","continent.","hemisphere."],"explanation":"Functional regions are tied together by movement and interaction around a node."},{"prompt":"Which factor most strongly influences climate near the equator?","correct":"High average solar angle throughout the year","distractors":["Permanent polar night","Great distance from the Sun compared with the poles","Low atmospheric pressure in every location"],"explanation":"Direct solar energy supports generally warm equatorial climates."},{"prompt":"Coastal locations often have milder temperatures than inland locations because:","correct":"water heats and cools more slowly than land.","distractors":["oceans receive no solar energy.","land has no heat capacity.","coasts are always at high elevation."],"explanation":"Large bodies of water moderate seasonal and daily temperature changes."},{"prompt":"Rain shadows commonly form on the:","correct":"leeward side of mountains.","distractors":["windward side where air first rises.","ocean floor only.","equator only."],"explanation":"Air loses moisture as it rises on the windward side, then descends and dries on the leeward side."},{"prompt":"Which is a push factor in migration?","correct":"Political persecution","distractors":["Greater job opportunities at the destination","Family reunification at the destination","A desirable climate at the destination"],"explanation":"Push factors encourage departure; pull factors attract migrants to a new place."},{"prompt":"Urbanization is the process by which:","correct":"an increasing share of a population lives in towns and cities.","distractors":["rural land becomes uninhabited everywhere.","national borders disappear.","all farming ends."],"explanation":"Industrialization and migration often drive city growth."},{"prompt":"Population density is calculated as:","correct":"population divided by land area.","distractors":["land area divided by elevation.","birth rate minus death rate only.","longitude multiplied by latitude."],"explanation":"Density expresses the average number of people per unit area."},{"prompt":"Which resource most directly influenced settlement in arid regions of the American West?","correct":"Reliable water supplies","distractors":["Abundant tropical rainfall","Year-round sea ice","Dense temperate rainforest everywhere"],"explanation":"Water availability constrains agriculture, cities, and industry in dry environments."},{"prompt":"A delta forms where:","correct":"a river deposits sediment near its mouth.","distractors":["a glacier removes all sediment.","two mountains collide.","groundwater evaporates deep underground."],"explanation":"Slowing river water deposits sediment, building landforms at some mouths."},{"prompt":"Human modification of a floodplain by paving and construction often:","correct":"increases runoff and flood risk.","distractors":["increases infiltration everywhere.","eliminates the watershed.","prevents all erosion."],"explanation":"Impervious surfaces reduce infiltration and move water rapidly into streams."},{"prompt":"Globalization refers to increasing:","correct":"economic, cultural, technological, and political connections across regions.","distractors":["isolation of every national economy.","distance between places.","elimination of migration."],"explanation":"Trade, communication, finance, and movement connect distant places more intensively."},{"prompt":"Which location factor is most important for a port city?","correct":"Access to navigable water and transportation networks","distractors":["Distance from all trade routes","Absence of a hinterland","Permanent closure to ships"],"explanation":"Ports depend on connections between maritime routes and inland markets."},{"prompt":"Subsistence agriculture is production primarily for:","correct":"the farmer’s household or local consumption.","distractors":["distant export markets only.","industrial manufacturing.","financial speculation."],"explanation":"Subsistence farming focuses on direct consumption rather than commercial sale."},{"prompt":"Which renewable resource is especially influenced by local topography and wind patterns?","correct":"Wind energy","distractors":["Coal","Uranium","Petroleum"],"explanation":"Wind-turbine output depends on airflow shaped by regional climate and terrain."},{"prompt":"Geographic information systems (GIS) are used to:","correct":"store, combine, analyze, and map spatial data.","distractors":["replace all field observations.","measure time without location.","translate every language automatically."],"explanation":"GIS connects data to locations and reveals spatial patterns and relationships."}]},"ss-economics":{"label":"Economics and Personal Finance","description":"Scarcity, markets, production, trade, indicators, public policy, banking, taxes, and economic decision-making.","group":"Economics","questions":[{"prompt":"Scarcity means that:","correct":"resources are limited relative to human wants.","distractors":["every good is unavailable.","money has no value.","people have no choices."],"explanation":"Scarcity makes choice and trade-offs unavoidable."},{"prompt":"Opportunity cost is:","correct":"the value of the next-best alternative given up.","distractors":["the money price only.","every benefit of a decision.","a tax imposed on imports."],"explanation":"Choosing one option sacrifices the best forgone alternative."},{"prompt":"Which is a factor of production?","correct":"Labor","distractors":["A consumer preference only","A sales receipt","A tariff rate only"],"explanation":"Land, labor, capital, and entrepreneurship are productive resources."},{"prompt":"In a market economy, prices primarily help:","correct":"coordinate decisions by signaling relative scarcity and demand.","distractors":["eliminate all scarcity.","guarantee equal income.","prevent competition."],"explanation":"Prices convey information and create incentives for buyers and sellers."},{"prompt":"If demand rises while supply remains unchanged, the equilibrium price generally:","correct":"rises.","distractors":["falls to zero.","remains legally fixed in every market.","becomes unrelated to scarcity."],"explanation":"Greater demand at each price creates upward pressure on the market price."},{"prompt":"If supply rises while demand remains unchanged, the equilibrium price generally:","correct":"falls.","distractors":["rises without limit.","must remain unchanged.","becomes a tax."],"explanation":"More supply at each price tends to lower equilibrium price and increase quantity."},{"prompt":"A tariff is:","correct":"a tax on imported goods.","distractors":["a subsidy paid to every consumer.","a limit on the quantity of money.","a privately issued stock."],"explanation":"Tariffs raise the cost of imports and may protect domestic producers."},{"prompt":"Specialization can increase productivity because workers and regions:","correct":"focus on tasks in which they are relatively efficient and trade for other goods.","distractors":["produce every good independently.","avoid all exchange.","eliminate comparative advantage."],"explanation":"Division of labor and comparative advantage can raise total output."},{"prompt":"Gross domestic product measures:","correct":"the market value of final goods and services produced within a country during a period.","distractors":["the total wealth of every citizen.","only government spending.","all unpaid household work exactly."],"explanation":"GDP is a flow measure of domestic final production."},{"prompt":"Inflation is a sustained increase in:","correct":"the general price level.","distractors":["real output only.","the value of money’s purchasing power.","the number of products with lower prices."],"explanation":"Inflation reduces the purchasing power of money when incomes do not keep pace."},{"prompt":"Unemployment statistics generally classify as unemployed people who:","correct":"do not have a job, are available for work, and are actively seeking work.","distractors":["are all children.","are retired and not seeking work.","work full time."],"explanation":"The labor-force definition requires active job search and availability."},{"prompt":"A progressive tax has an average rate that generally:","correct":"increases as taxable income increases.","distractors":["decreases as income increases.","is identical for every purchase only.","applies only to imports."],"explanation":"Progressive structures impose higher average rates at higher income levels."},{"prompt":"The Federal Reserve influences the U.S. economy mainly through:","correct":"monetary policy and the banking system.","distractors":["writing the federal budget.","collecting state property taxes.","operating every private bank directly."],"explanation":"The Fed affects interest rates, credit conditions, money, and financial stability."},{"prompt":"A budget deficit occurs when government:","correct":"spends more than it receives in revenue during a period.","distractors":["receives more than it spends.","has no debt.","exports more than it imports."],"explanation":"Deficits add to borrowing needs; surpluses occur when revenue exceeds spending."},{"prompt":"Which is an example of human capital?","correct":"Education and job skills","distractors":["A factory building","A barrel of oil","A parcel of land"],"explanation":"Human capital consists of knowledge, skills, health, and capacities embodied in people."},{"prompt":"An entrepreneur contributes to production by:","correct":"organizing resources, taking risks, and developing products or processes.","distractors":["eliminating all uncertainty.","setting every market price by law.","avoiding innovation."],"explanation":"Entrepreneurs combine resources and bear uncertainty in pursuit of opportunities."},{"prompt":"A monopoly exists when:","correct":"one seller dominates a market with substantial barriers to entry.","distractors":["many small firms sell identical products.","every consumer produces the product.","imports face no barriers."],"explanation":"A monopoly has market power because close competition is limited."},{"prompt":"External costs occur when:","correct":"some costs of an activity fall on people not directly involved in the transaction.","distractors":["all costs are paid by buyer and seller.","a firm earns profit.","a product has a listed price."],"explanation":"Pollution is a common example of a negative externality."}]},"ss-government":{"label":"Government, Citizenship, and Constitutional Principles","description":"Federalism, branches, rights, elections, Texas government, local government, rule of law, and civic participation.","group":"Civics","questions":[{"prompt":"Federalism divides power between:","correct":"the national government and state governments.","distractors":["the executive and a private corporation.","cities and foreign countries only.","judges and juries only."],"explanation":"The U.S. constitutional system assigns powers to national and state levels."},{"prompt":"Separation of powers distributes national authority among:","correct":"legislative, executive, and judicial branches.","distractors":["states, counties, and cities only.","political parties.","private businesses."],"explanation":"Separate branches reduce concentration of power."},{"prompt":"Checks and balances allow each branch to:","correct":"limit certain actions of the other branches.","distractors":["eliminate elections.","exercise every governmental power alone.","ignore the Constitution."],"explanation":"Examples include vetoes, confirmations, judicial review, and impeachment."},{"prompt":"The primary function of the legislative branch is to:","correct":"make laws.","distractors":["interpret laws in court.","command the military directly.","conduct local elections only."],"explanation":"Congress legislates, although it has other constitutional powers."},{"prompt":"The primary function of the executive branch is to:","correct":"enforce and administer laws.","distractors":["write constitutional amendments alone.","decide all court cases.","select state legislators."],"explanation":"The president and executive agencies implement federal law."},{"prompt":"The judicial branch primarily:","correct":"interprets laws and resolves legal disputes.","distractors":["collects all taxes.","negotiates every treaty.","writes statutes."],"explanation":"Courts apply constitutions and laws to cases and controversies."},{"prompt":"Popular sovereignty means that political authority ultimately comes from:","correct":"the people.","distractors":["a hereditary monarch.","foreign governments.","the military alone."],"explanation":"In a republic, legitimate government rests on the consent of the governed."},{"prompt":"Due process protects people by requiring government to:","correct":"follow fair legal procedures and respect protected rights.","distractors":["punish without hearings.","ignore written law.","deny notice of charges."],"explanation":"Due process limits arbitrary deprivation of life, liberty, or property."},{"prompt":"The First Amendment protects freedoms including:","correct":"religion, speech, press, assembly, and petition.","distractors":["quartering soldiers in homes.","trial by jury in every civil case only.","direct election of senators."],"explanation":"These five protections appear in the First Amendment."},{"prompt":"The Fourth Amendment protects against:","correct":"unreasonable searches and seizures.","distractors":["double jeopardy.","excessive congressional terms.","religious tests for office."],"explanation":"The amendment generally requires reasonableness and, for many searches, warrants based on probable cause."},{"prompt":"The power to declare war belongs constitutionally to:","correct":"Congress.","distractors":["the Supreme Court alone.","state governors collectively.","the president acting as legislator."],"explanation":"Congress has the power to declare war, while the president is commander in chief."},{"prompt":"The president’s veto can be overridden by:","correct":"a two-thirds vote in both houses of Congress.","distractors":["a simple majority of state governors.","one Supreme Court justice.","the vice president acting alone."],"explanation":"The Constitution requires a supermajority in each chamber."},{"prompt":"U.S. senators serve terms of:","correct":"six years.","distractors":["two years.","four years.","life."],"explanation":"Senate terms are six years, staggered so roughly one-third expire every two years."},{"prompt":"Members of the U.S. House of Representatives serve terms of:","correct":"two years.","distractors":["six years.","four years.","life."],"explanation":"The entire House is elected every two years."},{"prompt":"The electoral college is used to:","correct":"formally select the president and vice president.","distractors":["appoint Supreme Court justices.","ratify treaties.","draw congressional districts."],"explanation":"Voters choose electors allocated to states, and electoral votes determine the presidency."},{"prompt":"In Texas, the legislature is:","correct":"bicameral, consisting of the House and Senate.","distractors":["unicameral.","appointed by the governor.","part of the federal Congress."],"explanation":"Texas has a House of Representatives and a Senate."},{"prompt":"The Texas governor shares executive power with:","correct":"other independently elected statewide officials in a plural executive.","distractors":["no other executive officials.","the U.S. Senate only.","county juries only."],"explanation":"Texas disperses executive authority among several elected offices."},{"prompt":"Local governments commonly provide services such as:","correct":"police, fire protection, roads, parks, and utilities.","distractors":["declaring war.","issuing national currency.","negotiating treaties."],"explanation":"Municipal and county governments handle many services close to residents."},{"prompt":"Civic participation can include:","correct":"voting, contacting officials, serving on juries, and joining community organizations.","distractors":["obeying only laws one agrees with.","preventing others from speaking.","avoiding all public information."],"explanation":"Citizens participate through formal political acts and community engagement."},{"prompt":"The rule of law means that:","correct":"government officials and citizens are accountable to publicly known laws.","distractors":["leaders may act without legal limits.","laws apply only to private citizens.","courts must follow public opinion rather than law."],"explanation":"Rule of law rejects arbitrary power and requires legal accountability."}]},"ss-culture":{"label":"Culture and Society","description":"Cultural patterns, diversity, diffusion, identity, institutions, oral traditions, and cultural landscapes.","group":"Culture","questions":[{"prompt":"Culture includes a group’s shared:","correct":"beliefs, customs, language, institutions, and material practices.","distractors":["genetic traits only.","weather conditions only.","political borders only."],"explanation":"Culture is learned and transmitted through social life."},{"prompt":"Cultural diffusion is the:","correct":"spread of ideas, practices, or technologies from one society to another.","distractors":["complete disappearance of cultural contact.","division of a country into time zones.","measurement of population density."],"explanation":"Trade, migration, conquest, and communication all promote diffusion."},{"prompt":"An ethnic group is commonly defined by shared:","correct":"cultural heritage, ancestry, language, or historical identity.","distractors":["income only.","latitude only.","occupation only."],"explanation":"Ethnicity reflects perceived cultural and historical ties."},{"prompt":"A primary source is:","correct":"evidence created during the period or by a direct participant.","distractors":["a modern textbook summary only.","an encyclopedia entry written later.","a historian’s synthesis only."],"explanation":"Letters, laws, photographs, artifacts, and oral testimony may be primary sources."},{"prompt":"Which example best illustrates religious pluralism?","correct":"Multiple religious traditions coexist with legal protection for belief and practice.","distractors":["One faith is imposed by force.","All religious expression is prohibited.","Citizens are assigned beliefs by occupation."],"explanation":"Pluralism allows diverse communities to coexist within a shared civic order."},{"prompt":"Assimilation occurs when a group:","correct":"adopts many traits of a dominant culture, sometimes losing distinct practices.","distractors":["avoids all cultural contact.","creates a mountain range.","changes its birth rate only."],"explanation":"Assimilation is one possible result of sustained cultural interaction."},{"prompt":"Acculturation differs from complete assimilation because acculturation:","correct":"involves cultural change through contact without necessarily eliminating a group’s identity.","distractors":["requires total loss of all traditions.","occurs only through war.","is a biological process."],"explanation":"Groups can adopt selected practices while preserving distinct identities."},{"prompt":"Which institution most directly socializes children into shared norms and civic expectations?","correct":"Family and school","distractors":["Climate zone","Mineral deposit","Ocean current"],"explanation":"Families and schools are major institutions of socialization."},{"prompt":"A stereotype is:","correct":"an oversimplified generalization about a group.","distractors":["a carefully verified conclusion about every individual.","a geographic coordinate.","a constitutional amendment."],"explanation":"Stereotypes ignore individual variation and often reinforce bias."},{"prompt":"Historical perspective-taking requires a student to:","correct":"interpret choices within the values, knowledge, and circumstances of the time.","distractors":["judge the past only by present assumptions.","assume all people in an era agreed.","ignore evidence from participants."],"explanation":"Contextualization helps explain actions without requiring approval of them."},{"prompt":"Which factor often contributes to cultural diversity in cities?","correct":"Migration and immigration","distractors":["Complete isolation from transportation","A single occupation for all residents","Prohibition of communication"],"explanation":"Cities attract people from many regions and support varied institutions and networks."},{"prompt":"Oral traditions are important historical sources because they:","correct":"preserve memories and cultural knowledge, though they should be evaluated with other evidence.","distractors":["are always perfectly accurate.","contain no perspective.","cannot change over time."],"explanation":"Oral accounts provide valuable perspectives but, like all sources, require contextual evaluation."},{"prompt":"Which is an example of material culture?","correct":"A traditional tool or building style","distractors":["A belief about justice","A spoken myth only","A rule of etiquette only"],"explanation":"Material culture consists of physical objects created and used by a society."},{"prompt":"Which is an example of nonmaterial culture?","correct":"A language and system of values","distractors":["A ceramic vessel","A road network","A musical instrument as an object"],"explanation":"Nonmaterial culture includes ideas, norms, symbols, and language."},{"prompt":"Cultural landscapes are created when:","correct":"human activity leaves visible patterns on the environment.","distractors":["nature is entirely unaffected by people.","latitude disappears.","maps become inaccurate."],"explanation":"Farms, cities, sacred sites, roads, and architecture reflect culture in space."}]},"ss-skills":{"label":"Sources, Maps, Data, and Historical Reasoning","description":"Chronology, primary and secondary sources, bias, corroboration, causation, maps, graphs, and research claims.","group":"Social Studies Skills","questions":[{"prompt":"Which source is most useful for studying the daily experience of a Civil War soldier?","correct":"A diary written by a soldier during the war","distractors":["A modern atlas only","A weather forecast","A contemporary restaurant menu unrelated to the war"],"explanation":"A contemporaneous diary provides direct evidence of a participant’s experiences and perspective."},{"prompt":"A historian compares a law, newspaper editorials, and personal letters about the same event. This practice is called:","correct":"corroboration.","distractors":["urbanization.","monetary policy.","cartographic projection."],"explanation":"Corroboration checks claims across independent sources."},{"prompt":"Which question best evaluates source bias?","correct":"Who created the source, for what audience and purpose, and what information may be omitted?","distractors":["How many letters are in the title?","Is the source printed in color?","Does the source agree with me?"],"explanation":"Authorship, audience, purpose, and omissions help identify perspective and limitations."},{"prompt":"A timeline is most useful for analyzing:","correct":"chronology and sequence.","distractors":["latitude and longitude.","supply and demand only.","population density only."],"explanation":"Timelines arrange events in temporal order and can show duration or overlap."},{"prompt":"Which statement is a fact rather than an opinion?","correct":"Texas entered the Union in 1845.","distractors":["Texas has the most interesting history.","The Alamo is the most inspiring building.","Ranching is a better occupation than farming."],"explanation":"The date of annexation is verifiable; the other statements express judgments."},{"prompt":"A political cartoon should be analyzed by examining:","correct":"symbols, labels, exaggeration, context, and the cartoonist’s point of view.","distractors":["only whether it is humorous.","the paper size only.","whether every character is realistic."],"explanation":"Cartoons communicate arguments through visual conventions and historical context."},{"prompt":"Which graph best shows change in a state’s population across ten census years?","correct":"Line graph","distractors":["Circle graph for one year only","Unlabeled pictograph","A compass rose"],"explanation":"A line graph makes trends over ordered time visible."},{"prompt":"Which display best compares the percentage distribution of a budget among categories?","correct":"Circle graph","distractors":["Topographic map","Timeline","Climograph only"],"explanation":"A circle graph emphasizes parts of a whole, though a bar graph can also compare values."},{"prompt":"A map projection necessarily distorts some combination of:","correct":"area, shape, distance, or direction.","distractors":["historical chronology only.","the number of continents.","all place names."],"explanation":"A curved surface cannot be flattened without distortion."},{"prompt":"Which is the strongest evidence for a causal historical claim?","correct":"Multiple sources showing that the proposed cause preceded the event and influenced the decisions or conditions leading to it.","distractors":["One later opinion with no evidence.","A coincidence occurring afterward.","A source unrelated to the event."],"explanation":"Causation requires chronology, a plausible mechanism, and corroborated evidence."},{"prompt":"To distinguish correlation from causation, a student should ask whether:","correct":"other factors could explain the relationship and whether evidence shows a causal mechanism.","distractors":["the graph uses two colors.","both variables are measured in the same unit.","the relationship is personally appealing."],"explanation":"Correlation alone does not rule out confounding factors or reverse causation."},{"prompt":"Which statement correctly distinguishes primary and secondary sources?","correct":"Primary sources originate from the period or participants; secondary sources interpret evidence afterward.","distractors":["Primary sources are always unbiased.","Secondary sources contain no evidence.","Only books can be primary sources."],"explanation":"The distinction concerns relationship to the event, not automatic reliability."},{"prompt":"A reliable research claim should be supported by:","correct":"relevant evidence from credible sources with reasoning that connects evidence to the claim.","distractors":["a large font.","an anonymous statement with no citation.","repetition alone."],"explanation":"Source quality, relevance, and transparent reasoning make claims more defensible."},{"prompt":"Which method best identifies change and continuity over time?","correct":"Compare conditions at multiple points and explain both differences and persistent features.","distractors":["Study one date only.","Ignore developments that lasted.","List events without relationships."],"explanation":"Historical analysis should account for what changed, what remained, and why."},{"prompt":"A census table lists population by county. To compare counties of different size fairly, a student should calculate:","correct":"population density.","distractors":["longitude only.","total area plus population.","the alphabetical order of counties."],"explanation":"Density normalizes population by land area."}]},"ss-instruction":{"label":"Social Studies Inquiry, Instruction, and Assessment","description":"Disciplinary inquiry, discussion, simulations, scaffolds, formative assessment, civic reasoning, and evidence-based writing.","group":"Professional Application","questions":[{"prompt":"Which task best develops historical thinking rather than simple recall?","correct":"Compare two accounts of the same event and evaluate how perspective shapes each account.","distractors":["Copy a list of dates.","Memorize a definition without context.","Color a map without interpreting it."],"explanation":"Comparing accounts develops sourcing, contextualization, and corroboration."},{"prompt":"A teacher wants students to understand scarcity. Which activity is most appropriate?","correct":"Give groups limited resources and require them to make and justify trade-offs.","distractors":["Provide unlimited resources.","Ask students to copy the word scarcity ten times.","Avoid discussing choices."],"explanation":"A constrained decision makes scarcity and opportunity cost concrete."},{"prompt":"Which assessment best measures students’ ability to use geographic evidence?","correct":"Ask students to make a claim from a map and support it with specific spatial patterns.","distractors":["Ask for the map title only.","Grade handwriting only.","Require memorization of colors."],"explanation":"Evidence-based interpretation demonstrates geographic reasoning."},{"prompt":"When discussing a controversial historical issue, the teacher should:","correct":"use relevant evidence, establish respectful norms, and distinguish historical interpretation from unsupported opinion.","distractors":["present only one viewpoint as unquestionable.","avoid all primary sources.","allow personal attacks."],"explanation":"Structured evidence-based discussion supports civic and historical reasoning."},{"prompt":"Which scaffold helps an English learner analyze a primary source without lowering the historical goal?","correct":"Provide vocabulary support, chunk the document, and use guiding questions about author, audience, and claim.","distractors":["Replace the source with an unrelated coloring page.","Excuse the student from using evidence.","Remove all content vocabulary."],"explanation":"Language access can support the same analytical task."},{"prompt":"A formative assessment should be used to:","correct":"identify current understanding and adjust upcoming instruction.","distractors":["assign only a final grade.","rank students publicly.","replace all feedback."],"explanation":"Formative evidence guides instruction during learning."},{"prompt":"Which question promotes civic reasoning?","correct":"What constitutional principle is involved, what evidence supports each position, and what trade-offs result?","distractors":["Which answer is longest?","Which side is more popular in class?","Can the issue be solved without evidence?"],"explanation":"Civic reasoning applies principles and evidence while evaluating consequences."},{"prompt":"A simulation of a legislature is most effective when students:","correct":"use assigned roles, negotiate based on interests, and reflect on how rules shaped outcomes.","distractors":["vote randomly and skip reflection.","ignore procedures.","receive the final result in advance."],"explanation":"Role-based simulation plus debriefing connects experience to institutional concepts."},{"prompt":"Which sequence best supports inquiry in social studies?","correct":"Compelling question → source analysis → evidence-based claim → discussion or action","distractors":["Answer first → search only for confirmation","Vocabulary copying → no sources","Opinion poll → historical conclusion"],"explanation":"Inquiry organizes evidence around a meaningful question and culminates in a defensible conclusion."},{"prompt":"Students confuse a cause with an event that occurred later. The teacher should emphasize:","correct":"chronology and the requirement that a cause precede its effect.","distractors":["map scale.","spelling only.","population density."],"explanation":"Temporal sequence is necessary, though not sufficient, for causal explanation."},{"prompt":"Which use of local history is most academically valuable?","correct":"Connect a local site or oral history to broader state and national patterns while evaluating evidence.","distractors":["Treat every local story as automatically accurate.","Avoid comparison with other sources.","Study local names without context."],"explanation":"Local evidence can make larger historical processes concrete when critically analyzed."},{"prompt":"A rubric for an evidence-based essay should emphasize:","correct":"a clear claim, relevant evidence, accurate context, reasoning, and source use.","distractors":["page decoration.","length regardless of quality.","agreement with the teacher’s personal opinion."],"explanation":"These criteria measure disciplinary writing and argument."},{"prompt":"Which practice helps students detect misinformation online?","correct":"Lateral reading—check the author or organization using independent credible sources before trusting the page.","distractors":["Remain on the page and accept its self-description.","Share the claim before checking it.","Judge only by visual design."],"explanation":"Independent verification reveals reputation, funding, expertise, and prior fact-checking."},{"prompt":"When students interpret a graph, the teacher should prompt them first to examine:","correct":"title, variables, units, scale, source, and overall pattern.","distractors":["the favorite color used.","whether the graph supports a preferred conclusion.","the number of letters in the labels."],"explanation":"Graph interpretation begins with how the data are defined and displayed."},{"prompt":"Which approach best supports multiple perspectives without implying that all claims are equally valid?","correct":"Include varied viewpoints and evaluate each against relevant evidence and context.","distractors":["Treat evidence and unsupported assertion as equivalent.","Exclude marginalized perspectives.","Choose the most emotional account regardless of reliability."],"explanation":"Perspective matters, but claims still require evidence and contextual evaluation."}]}},"exams":{"ec6-social":{"id":"ec6-social","family":"TExES Core Subjects EC–6","code":"903","title":"Core Subjects EC–6 Social Studies","shortTitle":"EC–6 Social Studies 903","description":"Elementary social studies across Texas, U.S. and world history, geography, economics, government, culture, skills, and instruction.","fullCount":40,"duration":50,"forms":4,"topicVersions":3,"topicCount":10,"categories":["ss-texas","ss-us","ss-world","ss-geography","ss-economics","ss-government","ss-culture","ss-skills","ss-instruction"],"weights":{"ss-texas":6,"ss-us":6,"ss-world":3,"ss-geography":5,"ss-economics":4,"ss-government":5,"ss-culture":3,"ss-skills":4,"ss-instruction":4},"note":"The official Social Studies 903 subject exam has 40 selected-response questions. These forms preserve that length and sample the content and application competencies."},"core48-social":{"id":"core48-social","family":"TExES Core Subjects 4–8","code":"808","title":"Core Subjects 4–8 Social Studies","shortTitle":"Core 4–8 Social Studies 808","description":"Middle-level generalist preparation in history, geography, economics, government, culture, source analysis, and social studies instruction.","fullCount":42,"duration":50,"forms":4,"topicVersions":3,"topicCount":10,"categories":["ss-texas","ss-us","ss-world","ss-geography","ss-economics","ss-government","ss-culture","ss-skills","ss-instruction"],"weights":{"ss-texas":6,"ss-us":7,"ss-world":5,"ss-geography":5,"ss-economics":4,"ss-government":5,"ss-culture":2,"ss-skills":4,"ss-instruction":4},"note":"The official Social Studies 808 subject exam has 42 selected-response questions. The report uses broader disciplinary areas to make study priorities clear."},"social48":{"id":"social48","family":"TExES","code":"118","title":"Social Studies 4–8","shortTitle":"Social Studies 4–8 (118)","description":"Standalone middle-level social studies aligned to the official content and foundations/skills/instruction domains.","fullCount":100,"duration":285,"forms":4,"topicVersions":3,"topicCount":12,"categories":["ss-texas","ss-us","ss-world","ss-geography","ss-economics","ss-government","ss-culture","ss-skills","ss-instruction"],"weights":{"ss-texas":12,"ss-us":16,"ss-world":10,"ss-geography":10,"ss-economics":8,"ss-government":10,"ss-culture":5,"ss-skills":14,"ss-instruction":15},"note":"The official Social Studies 4–8 (118) exam contains 100 selected-response questions. These forms approximate the published 71% content and 29% foundations/skills/instruction balance."}},"labs":[]};const LETTERS=["A","B","C","D"];function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return h>>>0;}function rng(seed){let a=hash(seed)||1;return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;}}function shuffle(r,a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}function prep(raw,r,catId,i,seed){const opts=shuffle(r,[{text:raw.correct,ok:true},...raw.distractors.slice(0,3).map(text=>({text,ok:false}))]);return {id:`${catId}-${hash(seed+":"+i+":"+raw.prompt).toString(36)}`,prompt:raw.prompt,stimulus:raw.stimulus||"",choices:opts.map(x=>x.text),answer:opts.findIndex(x=>x.ok),explanation:raw.explanation,categoryId:catId,categoryLabel:DATA.categories[catId].label};}function categoryQuestions(id,count,seed){const c=DATA.categories[id],r=rng(seed),order=shuffle(r,c.questions.map((_,i)=>i)),out=[];for(let i=0;i<count;i++)out.push(prep(c.questions[order[i%order.length]],r,id,i,seed));return out;}function full(id,seed){const e=DATA.exams[id],r=rng(seed+":all");let qs=[];e.categories.forEach(c=>qs.push(...categoryQuestions(c,e.weights[c],seed+":"+c)));return shuffle(r,qs);}function topic(examId,catId,seed){const e=DATA.exams[examId];if(!e.categories.includes(catId))throw Error("Topic not in exam");return categoryQuestions(catId,e.topicCount,seed);}global.PracticeData={...DATA,LETTERS,generateFullExam:full,generateTopicQuiz:topic};})(window);